<?php
namespace App\Services;
use App\Models\{LoginChallenge,User};
use Illuminate\Support\Facades\{Hash,DB,Mail,Log};
use Illuminate\Support\Facades\Http;
class LoginChallengeService {
 public function begin(User $u, ?string $device, bool $alreadyHashed=false, int $sendCount=1): LoginChallenge { return DB::transaction(function()use($u,$device,$alreadyHashed,$sendCount){ $u=User::whereKey($u->id)->lockForUpdate()->first(); LoginChallenge::where('user_id',$u->id)->whereNull('consumed_at')->update(['consumed_at'=>now()]); $otp=(string)random_int(100000,999999); $c=LoginChallenge::create(['user_id'=>$u->id,'device_id_hash'=>$alreadyHashed?$device:UserSecurityService::deviceHash($device),'otp_hash'=>Hash::make($otp),'send_count'=>$sendCount,'expires_at'=>now()->addMinutes(10),'sent_at'=>now()]); try { $this->deliver($u,$otp); } catch (\Throwable $e) { $c->delete(); Log::error('Login OTP delivery failed',['user_id'=>$u->id,'error'=>$e->getMessage()]); UserSecurityService::recordEvent('otp_delivery_failed',$u,[], 'critical'); throw new \RuntimeException('otp_delivery_failed',0,$e); } UserSecurityService::recordEvent('otp_sent',$u,['challenge_id'=>$c->id,'send_count'=>$sendCount]); return $c; }); }
 private function deliver(User $u,string $otp): void { $message='Your Dupay login code is '.$otp.'. It expires in 10 minutes.'; $sent=false; if($u->email){ Mail::raw($message,function($m)use($u){$m->to($u->email)->subject('Your Dupay login code');}); $sent=true; } $webhook=env('OTP_SMS_WEBHOOK_URL'); if($webhook&&$u->phone_number){ $response=Http::timeout(10)->post($webhook,['to'=>$u->phone_number,'message'=>$message]); if(!$response->successful()) throw new \RuntimeException('sms_provider_failed'); $sent=true; } if(!$sent) throw new \RuntimeException('no_otp_delivery_channel'); }
 public function verify(LoginChallenge $c,string $otp): bool { return DB::transaction(function()use($c,$otp){ $c=LoginChallenge::whereKey($c->id)->lockForUpdate()->first(); if(!$c||$c->consumed_at||now()->gte($c->expires_at)) return false; if(!Hash::check($otp,$c->otp_hash)){ $c->increment('attempts'); return false; } $c->update(['consumed_at'=>now()]); return true; }); }
 public function registerDevice(User $u,LoginChallenge $c): void { if(!$c->device_id_hash)return; DB::table('user_devices')->updateOrInsert(['user_id'=>$u->id,'device_id_hash'=>$c->device_id_hash],['user_agent'=>request()->userAgent(),'last_ip'=>request()->ip(),'verified_at'=>now(),'last_seen_at'=>now(),'revoked_at'=>null,'updated_at'=>now(),'created_at'=>now()]); UserSecurityService::recordEvent('new_device_login',$u,['device_id_hash'=>$c->device_id_hash]); }
}
